const newConcept = ({ id, key, label, aliases, definition, objective, pitfalls, type, micro, article, resources, claim, signal, uncertainty, subject = 'msk', primary = 'SYS-MSK', secondary = 'DIS-PAT-T03', topic = 'Musculoskeletal system', subtopic = 'Bone and joint disorders' }) => ({
  label, id, canonical_key: key, aliases, ...conceptCommon, subject, primary_node_id: primary, secondary_node_ids: secondary, topic, subtopic, definition, explicit_objective: objective, pitfalls, concept_type: type, microtopic: micro, article_ids: article, related_article_ids: article, resource_ids: resources, exam_signal: signal, atomic_claim_ids: claim, original_wording: signal, uncertainty,
})
const updateConcept = ({ id, article, resources, claim, definition, objective, pitfalls, signal, uncertainty }) => {
  const row = requireCurrent(currentConcepts, id)
  row.definition = appendText(row.definition, definition)
  row.explicit_objective = appendText(row.explicit_objective, objective)
  row.pitfalls = appendText(row.pitfalls, pitfalls)
  row.article_ids = uniqueLines(row.article_ids, article)
  row.related_article_ids = uniqueLines(row.related_article_ids, article)
  row.resource_ids = uniqueLines(row.resource_ids, resources)
  row.atomic_claim_ids = uniqueLines(row.atomic_claim_ids, claim)
  row.exam_signal = appendText(row.exam_signal, signal)
  row.original_wording = appendText(row.original_wording, signal)
  row.uncertainty = uniqueLines(row.uncertainty === '[clear]' ? '' : row.uncertainty, uncertainty)
  return row
}

