const updateArticle = ({ id, concepts, questions, sources, conflict }) => {
  const row = requireCurrent(currentArticles, id)
  const specs = claimsByArticle(id)
  const extension = specs.map((spec) => spec.text).join('\n\n')
  row.summary = appendText(row.summary, `Family-163 Q59-Q73 adds ${questions.length} safe source occurrences while preserving Q59, Q66 and Q73 as conflict holds.`)
  row.sections = appendText(row.sections, `### Family-163 Q59-Q73 extension\n${extension}\n\nEvery included item preserves its literal wording, option order and agreeing formal/red keys. Q59, Q66 and Q73 remain excluded because their answer layers conflict. These Draft additions are local assessment explanations rather than clinical guidance.\n\n### Extension limitations\nThe bank names an author and collectors but no official exam sitting, cohort or date. Its two answer layers are same-source evidence. Teaching sources support only the stated bounded context; source-specific treatment, test, serology and prognosis relations remain direct-assessment-bound.`)
  row.hold_these = appendText(row.hold_these, extension)
  row.related_concepts = uniqueLines(row.related_concepts, concepts)
  row.question_ids = uniqueLines(row.question_ids, questions.map((number) => `Q-HU-LCS103-MSK-F163-${String(number).padStart(2, '0')}`))
  row.resource_ids = uniqueLines(row.resource_ids, sources)
  row.article_source_ids = uniqueLines(row.article_source_ids, sources)
  row.claim_ids = uniqueLines(row.claim_ids, specs.map((spec) => `CLM-HULCS103-F163-${spec.code}-01`))
  row.span_ids = uniqueLines(row.span_ids, specs.map((spec) => `SPN-HULCS103-F163-${spec.code}-01`))
  row.annotations = appendText(row.annotations, specs.map((spec) => `### definition_of · ${spec.concept}\nQuote: ${spec.text}\nBlock: Family-163 Q59-Q73 extension`).join('\n\n'))
  row.callout_evidence = appendText(row.callout_evidence, specs.map((spec) => `### ${spec.text}\nClaims: CLM-HULCS103-F163-${spec.code}-01\nCitations: CIT-HULCS103-F163-${spec.code}-ASSESS-01, CIT-HULCS103-F163-${spec.code}-TEACH-01\nSpan: SPN-HULCS103-F163-${spec.code}-01`).join('\n\n'))
  row.conflicts = uniqueLines(row.conflicts === '[clear]' ? '' : row.conflicts, conflict)
  row.notes = appendText(row.notes, 'This metadata-preserving same-ID update retains every prior link, university field and evidence limitation before appending the approved Q59-Q73 subset.')
  return row
}
